<?php defined('C5_EXECUTE') or die('Access Denied.');
$app=\Concrete\Core\Support\Facade\Application::getFacadeApplication();
$csrf=(string)$app->make('helper/validation/token')->generate('xavi_sky_action');
?>
<style>
html:has(#xavi-sky-app),html:has(#xavi-sky-app) body{background:#000;color:#fff;width:100%;max-width:none;overflow-x:hidden}
html:has(#xavi-sky-app) .ccm-page:has(#xavi-sky-app),html:has(#xavi-sky-app) main:has(#xavi-sky-app),html:has(#xavi-sky-app) .container:has(#xavi-sky-app),html:has(#xavi-sky-app) .container-fluid:has(#xavi-sky-app),html:has(#xavi-sky-app) .row:has(#xavi-sky-app),html:has(#xavi-sky-app) [class^="col-"]:has(#xavi-sky-app){width:100%!important;max-width:none!important;margin:0!important;padding-left:0!important;padding-right:0!important}
#xavi-sky-app{font:14px/1.45 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;background:#000;color:#fff;min-height:78vh;width:100dvw;margin-left:calc(50% - 50dvw);padding:14px;box-sizing:border-box}
#xavi-sky-app *{box-sizing:border-box}.xs-head{display:flex;gap:12px;align-items:center;flex-wrap:wrap;border:1px solid #fff;padding:10px;margin-bottom:10px}.xs-head h1{font-size:20px;margin:0}.xs-muted{opacity:.68}.xs-spacer{flex:1}.xs-safe{border:1px solid #fff;padding:4px 7px;font-weight:700}.xs-btn,.xs-in,.xs-sel{background:#000;color:#fff;border:1px solid #fff;border-radius:0;padding:7px 9px}.xs-btn{cursor:pointer}.xs-btn:hover{background:#fff;color:#000}.xs-btn:disabled{opacity:.42;cursor:not-allowed;background:#000;color:#fff}.xs-danger{border-style:dashed}.xs-grid{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr));gap:8px;margin-bottom:10px}.xs-card,.xs-panel,.xs-toolbar{border:1px solid #fff;background:#000}.xs-card{padding:10px}.xs-card b{display:block;font-size:22px}.xs-tabs{display:flex;gap:0;margin-bottom:8px;flex-wrap:wrap}.xs-tab{border:1px solid #fff;background:#000;color:#fff;padding:7px 12px;cursor:pointer;margin-right:-1px}.xs-tab.on{background:#fff;color:#000}.xs-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:8px;margin-bottom:8px}.xs-toolbar label{display:flex;gap:5px;align-items:center}.xs-toolbar .xs-in{min-width:190px}.xs-panel{overflow:auto}.xs-panel table{width:100%;border-collapse:collapse;min-width:1100px}.xs-panel th,.xs-panel td{border-bottom:1px solid #333;padding:8px;text-align:left;vertical-align:top}.xs-panel th{position:sticky;top:0;background:#000;border-bottom:1px solid #fff;z-index:2}.xs-score{font-variant-numeric:tabular-nums;font-weight:700}.xs-json{white-space:pre-wrap;max-width:520px;word-break:break-word}.xs-error{border:1px solid #fff;padding:10px;margin-bottom:10px}.xs-actions{display:flex;gap:5px;flex-wrap:wrap;min-width:260px}.xs-link{color:#fff}.xs-bio,.xs-why{max-width:430px;white-space:normal}.xs-tags{display:flex;gap:4px;flex-wrap:wrap}.xs-tag{border:1px solid #555;padding:2px 5px;white-space:nowrap}.xs-state{font-weight:700}.xs-state-followed{border-bottom:2px solid #fff}.xs-state-dismissed{opacity:.6}.xs-empty{padding:18px}.xs-profile{min-width:240px}.xs-num{text-align:right;font-variant-numeric:tabular-nums}.xs-note{padding:8px;border-left:3px solid #fff;margin:8px 0}.xs-hidden{display:none!important}@media(max-width:1000px){.xs-grid{grid-template-columns:repeat(2,1fr)}.xs-panel table{min-width:900px}}
</style>
<div id="xavi-sky-app">
  <div class="xs-head">
    <h1>Xavi-Sky</h1>
    <span class="xs-muted">hourly Bluesky discovery / ranking / manual curation</span>
    <span class="xs-safe">NO AUTOMATIC FOLLOWS</span>
    <span class="xs-spacer"></span>
    <span id="xs-refresh-state" class="xs-muted">loading…</span>
    <button class="xs-btn" id="xs-refresh">Refresh</button>
  </div>
  <div class="xs-note">The background worker only searches and ranks public accounts. A Bluesky follow can happen only after you click <b>Follow</b> here and confirm it.</div>
  <div id="xs-error"></div>
  <div class="xs-grid" id="xs-cards"></div>
  <div class="xs-tabs">
    <button class="xs-tab on" data-tab="queue">Review Queue</button>
    <button class="xs-tab" data-tab="candidates">All Candidates</button>
    <button class="xs-tab" data-tab="history">Decisions</button>
    <button class="xs-tab" data-tab="packs">Starter Packs</button>
    <button class="xs-tab" data-tab="diagnostics">Diagnostics</button>
  </div>
  <div class="xs-toolbar" id="xs-toolbar">
    <label>Account <select id="xs-account" class="xs-sel"></select></label>
    <label>Search <input id="xs-q" class="xs-in" placeholder="handle, bio, rationale"></label>
    <label>Theme <select id="xs-theme" class="xs-sel"><option value="">all</option></select></label>
    <label>Min followers <input id="xs-min-followers" class="xs-in" type="number" min="0" value="25" style="min-width:90px;width:100px"></label>
    <label>Sort <select id="xs-sort" class="xs-sel"><option value="score">quality score</option><option value="followers">followers</option><option value="activity">posts/activity</option><option value="recent">recently seen</option></select></label>
    <button class="xs-btn" id="xs-apply">Apply</button>
  </div>
  <div class="xs-panel" id="xs-panel"><div class="xs-empty">Loading…</div></div>
</div>
<script>
(()=>{
const CSRF=<?=json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const A={status:'/api/xavi/sky/status',events:'/api/xavi/sky/events',candidates:'/api/xavi/sky/candidates',packs:'/api/xavi/sky/starter-packs',accounts:'/api/xavi/sky/accounts',queue:'/api/xavi/sky/follow-queue',history:'/api/xavi/sky/review-history',review:'/api/xavi/sky/review',follow:'/api/xavi/sky/follow'};
const panel=document.getElementById('xs-panel'),err=document.getElementById('xs-error'),cards=document.getElementById('xs-cards'),state=document.getElementById('xs-refresh-state');
const accountEl=document.getElementById('xs-account'),qEl=document.getElementById('xs-q'),themeEl=document.getElementById('xs-theme'),minEl=document.getElementById('xs-min-followers'),sortEl=document.getElementById('xs-sort');
let tab='queue',cache={};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ago=s=>{if(!s)return 'never';const n=Date.now()-new Date(s).getTime();if(n<60000)return Math.max(0,Math.round(n/1000))+'s ago';if(n<3600000)return Math.round(n/60000)+'m ago';if(n<86400000)return Math.round(n/3600000)+'h ago';return Math.round(n/86400000)+'d ago'};
const parseJson=(s,f)=>{try{return JSON.parse(s||'')??f}catch{return f}};
async function get(url){const r=await fetch(url,{credentials:'same-origin',cache:'no-store'});const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{d={error:t}}if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);return d;}
async function post(url,body){const r=await fetch(url,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Xavi-Sky-CSRF':CSRF},body:JSON.stringify(body)});const t=await r.text();let d={};try{d=t?JSON.parse(t):{}}catch{d={error:t}}if(!r.ok)throw new Error(d.error||`HTTP ${r.status}`);return d;}
function card(label,value,sub=''){return `<div class="xs-card"><span class="xs-muted">${esc(label)}</span><b>${esc(value)}</b><span class="xs-muted">${esc(sub)}</span></div>`}
function currentAccount(){return accountEl.value||cache.accounts?.accounts?.[0]?.handle||'';}
function filterParams(){const p=new URLSearchParams({limit:'150',account:currentAccount(),q:qEl.value.trim(),theme:themeEl.value,minFollowers:String(Math.max(0,Number(minEl.value||0))),sort:sortEl.value});return p.toString();}
function fillAccounts(){const rows=cache.accounts?.accounts||[],old=accountEl.value;accountEl.innerHTML=rows.map(a=>`<option value="${esc(a.handle)}">${esc(a.handle)}</option>`).join('');if(rows.some(a=>a.handle===old))accountEl.value=old;}
function fillThemes(){const keep=themeEl.value,themes=new Set();for(const c of cache.candidates?.candidates||[])for(const t of parseJson(c.themes_json,[]))if(t&&String(t)!=='followback')themes.add(String(t));themeEl.innerHTML='<option value="">all</option>'+[...themes].sort().map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');if(themes.has(keep))themeEl.value=keep;}
function renderCards(){const s=cache.status||{},lr=s.lastRun||{},ac=cache.accounts?.accounts||[];cards.innerHTML=card('Candidates',s.candidateCount??0,'ranked public accounts')+card('Dismissed',s.dismissedCount??0,'manual decisions')+card('Snoozed',s.snoozedCount??0,'temporarily hidden')+card('Followed',s.followedCount??0,'manual follows recorded')+card('Bluesky accounts',ac.length,ac.length?'manual actions available':'credentials not configured')+card('Last discovery',lr.status||'none',lr.finished_at?ago(lr.finished_at):'');}
function tags(c){const ts=parseJson(c.themes_json,[]),ss=parseJson(c.sources_json,[]);return `<div class="xs-tags">${ts.map(t=>`<span class="xs-tag">${esc(t)}</span>`).join('')}${ss.slice(0,3).map(t=>`<span class="xs-tag xs-muted">${esc(t)}</span>`).join('')}</div>`;}
function breakdown(c){const b=parseJson(c.score_breakdown_json,{}),parts=[];for(const [k,v] of Object.entries(b||{})){if(typeof v==='number')parts.push(`${k}: ${Number(v).toFixed(2)}`);else if(typeof v==='string'||typeof v==='boolean')parts.push(`${k}: ${String(v)}`);}return parts.slice(0,5).join(' · ');}
function why(c){const r=String(c.rationale||'').trim();const b=breakdown(c);return `<div class="xs-why">${r?esc(r):'<span class="xs-muted">Ranked by curator relevance, activity and audience signals.</span>'}${b?`<br><span class="xs-muted">${esc(b)}</span>`:''}</div>`;}
function profile(c){return `<div class="xs-profile"><b>${esc(c.display_name||c.handle||c.did)}</b><br>${c.handle?`<a class="xs-link" target="_blank" rel="noopener" href="https://bsky.app/profile/${encodeURIComponent(c.handle)}">@${esc(c.handle)}</a>`:''}<div class="xs-bio xs-muted">${esc(c.description||'')}</div></div>`;}
function actionButtons(c,account){return `<div class="xs-actions"><button class="xs-btn xs-follow" data-account="${esc(account)}" data-did="${esc(c.did)}" data-handle="${esc(c.handle||c.did)}">Follow</button><button class="xs-btn xs-snooze" data-account="${esc(account)}" data-did="${esc(c.did)}">Snooze</button><button class="xs-btn xs-dismiss xs-danger" data-account="${esc(account)}" data-did="${esc(c.did)}">Dismiss</button></div>`;}
function bindReviewActions(){panel.querySelectorAll('.xs-follow').forEach(b=>b.addEventListener('click',()=>followOne(b)));panel.querySelectorAll('.xs-snooze').forEach(b=>b.addEventListener('click',()=>snoozeOne(b)));panel.querySelectorAll('.xs-dismiss').forEach(b=>b.addEventListener('click',()=>reviewOne(b,'dismiss')));panel.querySelectorAll('.xs-restore').forEach(b=>b.addEventListener('click',()=>reviewOne(b,'queue')));}
async function loadTab(){const account=currentAccount();if(tab==='queue'&&account)cache.queue=await get(A.queue+'?'+filterParams());else if(tab==='history'&&account)cache.history=await get(A.history+'?limit=300&account='+encodeURIComponent(account));else if(tab==='packs')cache.packs=await get(A.packs);else if(tab==='diagnostics')cache.events=await get(A.events+'?limit=160');}
async function refresh(full=true){state.textContent='refreshing…';err.innerHTML='';try{cache.status=await get(A.status);cache.accounts=await get(A.accounts);if(full||!cache.candidates)cache.candidates=await get(A.candidates+'?limit=1000&sort=score');fillAccounts();fillThemes();await loadTab();renderCards();render();state.textContent='updated '+new Date().toLocaleTimeString();}catch(e){err.innerHTML=`<div class="xs-error">${esc(e.message)}${e.message==='auth'?' — sign in to Xavi first.':''}</div>`;state.textContent='error';}}
function render(){document.getElementById('xs-toolbar').classList.toggle('xs-hidden',tab==='packs'||tab==='diagnostics');if(tab==='queue')return renderQueue();if(tab==='candidates')return renderCandidates();if(tab==='history')return renderHistory();if(tab==='packs')return renderPacks();return renderDiagnostics();}
function renderQueue(){const account=currentAccount(),rows=cache.queue?.queue||[];if(!account){panel.innerHTML='<div class="xs-empty">Configure a Bluesky account first.</div>';return;}if(!rows.length){panel.innerHTML='<div class="xs-empty">No accounts match the current review filters. Lower the minimum followers, change theme/search, or wait for the next discovery run.</div>';return;}panel.innerHTML=`<table><thead><tr><th>#</th><th>Score</th><th>Account</th><th>Followers</th><th>Posts</th><th>Signals</th><th>Why it ranked</th><th>Manual actions</th></tr></thead><tbody>${rows.map((c,i)=>`<tr><td>${i+1}</td><td class="xs-score">${Number(c.score||0).toFixed(2)}</td><td>${profile(c)}</td><td class="xs-num">${esc(c.followers_count??'')}</td><td class="xs-num">${esc(c.posts_count??'')}</td><td>${tags(c)}</td><td>${why(c)}</td><td>${actionButtons(c,account)}</td></tr>`).join('')}</tbody></table>`;bindReviewActions();}
function renderCandidates(){const account=currentAccount(),q=qEl.value.trim().toLowerCase(),theme=themeEl.value,min=Math.max(0,Number(minEl.value||0));let rows=(cache.candidates?.candidates||[]).filter(c=>(!q||[c.handle,c.display_name,c.description,c.rationale].some(v=>String(v||'').toLowerCase().includes(q)))&&(!theme||parseJson(c.themes_json,[]).includes(theme))&&Number(c.followers_count||0)>=min);if(sortEl.value==='followers')rows.sort((a,b)=>Number(b.followers_count||0)-Number(a.followers_count||0));else if(sortEl.value==='activity')rows.sort((a,b)=>Number(b.posts_count||0)-Number(a.posts_count||0));else if(sortEl.value==='recent')rows.sort((a,b)=>String(b.last_seen_at).localeCompare(String(a.last_seen_at)));else rows.sort((a,b)=>Number(b.score||0)-Number(a.score||0));rows=rows.slice(0,400);panel.innerHTML=`<table><thead><tr><th>#</th><th>Score</th><th>Account</th><th>Followers</th><th>Posts</th><th>Signals</th><th>Why it ranked</th><th>Per-account state</th><th>Manual actions</th></tr></thead><tbody>${rows.map((c,i)=>`<tr><td>${i+1}</td><td class="xs-score">${Number(c.score||0).toFixed(2)}</td><td>${profile(c)}</td><td class="xs-num">${esc(c.followers_count??'')}</td><td class="xs-num">${esc(c.posts_count??'')}</td><td>${tags(c)}</td><td>${why(c)}</td><td class="xs-json">${esc(c.account_states||'{}')}</td><td>${account?actionButtons(c,account):''}</td></tr>`).join('')}</tbody></table>`;bindReviewActions();}
function renderHistory(){const rows=cache.history?.history||[],account=currentAccount();if(!rows.length){panel.innerHTML='<div class="xs-empty">No manual decisions recorded for this account yet.</div>';return;}panel.innerHTML=`<table><thead><tr><th>State</th><th>Account</th><th>When</th><th>Detail</th><th>Signals</th><th>Action</th></tr></thead><tbody>${rows.map(c=>{const canRestore=['dismissed','snoozed','unavailable','queued'].includes(c.state);return `<tr><td class="xs-state xs-state-${esc(c.state)}">${esc(c.state)}</td><td>${profile(c)}</td><td>${esc(ago(c.last_action_at))}</td><td>${esc(c.state==='snoozed'&&c.detail?'until '+new Date(c.detail).toLocaleString():c.detail||'')}</td><td>${why(c)}</td><td>${canRestore?`<button class="xs-btn xs-restore" data-account="${esc(account)}" data-did="${esc(c.did)}">Return to queue</button>`:''}</td></tr>`}).join('')}</tbody></table>`;bindReviewActions();}
function renderPacks(){const rows=cache.packs?.starterPacks||[];panel.innerHTML=`<table><thead><tr><th>Starter pack</th><th>Themes</th><th>First seen</th><th>Last seen</th></tr></thead><tbody>${rows.map(p=>`<tr><td><a class="xs-link" target="_blank" rel="noopener" href="${esc(p.url)}">${esc(p.url)}</a></td><td>${esc(p.themes_json)}</td><td>${esc(ago(p.first_seen_at))}</td><td>${esc(ago(p.last_seen_at))}</td></tr>`).join('')}</tbody></table>`;}
function renderDiagnostics(){const s=cache.status||{},lr=s.lastRun||{},rows=cache.events?.events||[];panel.innerHTML=`<div style="padding:12px"><b>Runtime mode:</b> discovery-only / manual-follow-only<br><b>Last run:</b> ${esc(lr.status||'none')} ${lr.finished_at?'· '+esc(ago(lr.finished_at)):''}<br><b>Database:</b> ${esc(s.db||'')}<br><b>Local events:</b> ${esc(s.eventCount??0)}</div><table><thead><tr><th>Seq</th><th>When</th><th>Event</th><th>Entity</th><th>Account</th><th>Payload</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.ingest_seq)}</td><td>${esc(ago(e.created_at))}</td><td>${esc(e.event_type)}</td><td>${esc(e.entity_type)}<br><span class="xs-muted">${esc(e.entity_id)}</span></td><td>${esc(e.account_handle||'')}</td><td class="xs-json">${esc(e.payload_json)}</td></tr>`).join('')}</tbody></table>`;}
async function followOne(btn){const account=btn.dataset.account,did=btn.dataset.did,handle=btn.dataset.handle||did;if(!account||!did)return;if(!confirm(`Follow @${handle} using ${account}?\n\nThis is the only action here that writes to Bluesky.`))return;btn.disabled=true;const old=btn.textContent;btn.textContent='Following…';err.innerHTML='';try{const r=await post(A.follow,{manual:true,accountHandle:account,did});btn.textContent=r.already?'Already followed':'Followed';await refresh(false);}catch(e){btn.disabled=false;btn.textContent=old;err.innerHTML=`<div class="xs-error">Follow failed: ${esc(e.message)}</div>`;}}
async function snoozeOne(btn){const raw=prompt('Snooze this account for how many days?','7');if(raw===null)return;const days=Math.max(1,Math.min(90,Number(raw)||7));await reviewOne(btn,'snooze',days);}
async function reviewOne(btn,action,days=7){const account=btn.dataset.account,did=btn.dataset.did;if(!account||!did)return;btn.disabled=true;err.innerHTML='';try{await post(A.review,{accountHandle:account,did,action,days});await refresh(false);}catch(e){btn.disabled=false;err.innerHTML=`<div class="xs-error">Review action failed: ${esc(e.message)}</div>`;}}
document.querySelectorAll('.xs-tab').forEach(b=>b.addEventListener('click',async()=>{document.querySelectorAll('.xs-tab').forEach(x=>x.classList.remove('on'));b.classList.add('on');tab=b.dataset.tab;await refresh(false)}));
document.getElementById('xs-refresh').addEventListener('click',()=>refresh(true));document.getElementById('xs-apply').addEventListener('click',()=>{if(tab==='candidates')renderCandidates();else refresh(false)});accountEl.addEventListener('change',()=>refresh(false));qEl.addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('xs-apply').click()});
refresh(true);setInterval(()=>refresh(false),60000);
})();
</script>
